<?php
if (!defined('BC_CRYPTO_CUSTODY_PAGE')) {http_response_code(404);exit;}
header('Cache-Control: no-store, private, max-age=0');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');
$platform=BC_CRYPTO_CUSTODY_PAGE==='spadmin';
$actor=$platform?($get_logged_spadmin_details??null):($get_logged_admin_details??null);
if (!$actor||empty($actor['id'])||(int)($actor['status']??0)!==1||!empty($actor['is_blocked'])||!empty($actor['force_password_change'])) {http_response_code(403);exit('Access denied. Complete required account security setup.');}
$method=$_SERVER['REQUEST_METHOD']??'GET';
if (!in_array($method,['GET','POST'],true)) {http_response_code(405);header('Allow: GET, POST');exit;}
if (!$platform && $method==='POST') {http_response_code(403);exit('Independent platform review is required; vendor self-approval is not available.');}
require_once __DIR__.'/bc-crypto-custody-management.php';
$env=in_array($_GET['environment']??null,['testnet','mainnet'],true)?$_GET['environment']:'testnet';
$selected=$_GET['account']??'';
if (!is_string($selected)||!preg_match('/^[a-f0-9]{64}$/D',$selected)) $selected='';
$notice='';$evidence=null;$row=null;$accounts=[];$events=[];$route_candidates=[];$routes_schema=true;$poll_schema=true;$poll_streams=[];$schema=true;
if ($method==='POST') {
    try {
        $result=bc_crypto_custody_manage((int)$actor['id'],$_POST);
        $env=$_POST['environment'];$selected=$result['custody_account'];
        if (array_key_exists('text',$result)) $evidence=$result['text'];
        else {
            if (!empty($result['worker_recovered'])) $summary='Expired unknown attempt recovered and old grant fenced. Cursor/evidence unchanged; retry backoff still applies.';
            elseif (!empty($result['worker_grant_updated'])) $summary='Worker grant updated: '.$result['worker_grant_id'].'. No scheduler or funds enabled.';
            elseif (!empty($result['alert_acknowledged'])) $summary='Alert acknowledged only. Retry escalation, evidence, streams and financial restrictions unchanged.';
            elseif (!empty($result['poll_updated'])) $summary='Polling stream updated; no imports or credits. Stream '.$result['stream_id'].' revision '.$result['revision'].'. ';
            elseif (!empty($result['deposit_page_inspected'])) $summary='Deposit page inspected; no imports or checkpoint advanced. Encrypted evidence digest: ';
            elseif (!empty($result['route_candidate_updated'])) $summary='Route candidate updated; no funding address activated. Evidence digest: ';
            elseif (!empty($result['master_address_inspected'])) $summary='Master address inventory inspected, not customer allocation. Encrypted evidence digest: ';
            elseif (!empty($result['provider_identity_compared'])) $summary='Provider UID matched at inspection time. Encrypted evidence digest: ';
            else $summary='Evidence stored. Digest: ';
            $_SESSION['crypto_custody_notice']=!empty($result['worker_recovered'])?$summary:(!empty($result['worker_grant_updated'])?$summary:(!empty($result['alert_acknowledged'])?$summary:(!empty($result['poll_updated'])?$summary.(isset($result['evidence_hash'])?'Encrypted evidence digest: '.$result['evidence_hash']:''):(isset($result['evidence_hash'])?$summary.$result['evidence_hash']:'Local custody review updated. No live capability activated.'))));
            header('Location: CryptoCustody.php?environment='.rawurlencode($env).'&account='.$selected);exit;
        }
    } catch(Throwable $ex) {
        $notice=preg_match('/^(?:crypto|bybit)_[a-z_]+$/D',$ex->getMessage())?$ex->getMessage():'crypto_custody_unavailable';
        http_response_code(400);
    }
}
if ($platform) {
    try {
        $list=bc_q('SELECT custody_account,revision,document FROM sas_crypto_v2_custody_accounts WHERE environment=? ORDER BY custody_account LIMIT 100',[$env]);
        if (!($list instanceof mysqli_result)) throw new RuntimeException('schema');
        while($a=mysqli_fetch_assoc($list)) $accounts[]=$a;
        if ($selected!=='') {
            $row=bc_q_row('SELECT * FROM sas_crypto_v2_custody_accounts WHERE custody_account=? AND environment=?',[$selected,$env]);
            if ($row) {
                $audit=bc_q('SELECT revision,actor_id,action,created_at FROM sas_crypto_v2_custody_audit WHERE custody_account=? ORDER BY revision DESC LIMIT 30',[$selected]);
                if (!($audit instanceof mysqli_result)) throw new RuntimeException('schema');
                while($a=mysqli_fetch_assoc($audit)) $events[]=$a;
            }
        }
    } catch(Throwable $ex) {$schema=false;$notice='crypto_custody_schema_required';}
}
if ($platform && $row) {
    try {
        $candidates=bc_q('SELECT * FROM sas_crypto_v2_route_candidates WHERE custody_account=? AND environment=? ORDER BY id DESC LIMIT 30',[$selected,$env]);
        if (!($candidates instanceof mysqli_result)) throw new RuntimeException('schema');
        while($candidate=mysqli_fetch_assoc($candidates)) $route_candidates[]=$candidate;
    } catch(Throwable $ex) {$routes_schema=false;}
}
if ($platform && $row) {
    try {
        $poll_list=bc_q('SELECT s.stream_id,s.vendor_id,s.custody_revision,s.revision,s.page_count,s.state,s.valid_until_epoch,COALESCE(l.expires_at_epoch,0) AS lease_until FROM sas_crypto_v2_poll_streams s LEFT JOIN sas_crypto_v2_poll_leases l ON l.stream_id=s.stream_id WHERE s.custody_account=? AND s.environment=? ORDER BY s.created_at DESC,s.stream_id LIMIT 20',[$selected,$env]);
        if (!($poll_list instanceof mysqli_result))throw new RuntimeException('schema');
        while($p=mysqli_fetch_assoc($poll_list))$poll_streams[]=$p;
    }catch(Throwable $ex){$poll_schema=false;}
}
if (isset($_SESSION['crypto_custody_notice'])) {$notice=$_SESSION['crypto_custody_notice'];unset($_SESSION['crypto_custody_notice']);}
$e=function($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');};
$area=$platform?'spadmin':'admin';
require_once __DIR__.'/bc-plate-admin.php';bc_adm_head('Crypto custody reviews',['area'=>$area]);bc_adm_sidebar(['area'=>$area]);bc_adm_topbar(['area'=>$area,'title'=>'CRYPTO CUSTODY REVIEWS','crumb'=>'Crypto / Custody']);
?>
